// embedded_sysroot.h — the vendored link sysroot embedded as data.
//
// Go/Zig ship their CRT/libc inside the compiler; pli embeds the link
// sysroot as generated byte arrays (see scripts/gen_sysroot_embed.py), so
// release archives contain only pli(.exe) — no musl/, mingw/, sdk/ sidecar.
// At link time the driver materializes these blobs to a temp dir (hostcrt).
#pragma once
#include <cstddef>

namespace pli {
// One sysroot file: sysroot-relative path (e.g. "crt1.o",
// "usr/lib/libSystem.tbd") plus its bytes.
struct SysrootFile {
  const char* path;
  const unsigned char* data;
  size_t len;
};
// Files embedded for this build's host OS (musl set on Linux, mingw set on
// Windows, .tbd stubs on macOS). Empty (n=0, null return) when the build
// embedded none — arch mismatch or missing sources — in which case user links
// fail with a clear error (no host-toolchain fallback).
const SysrootFile* embeddedSysrootFiles(size_t* n);
// Which link path the set feeds: "musl", "mingw", or "sdk" ("" when none).
const char* embeddedSysrootName();
// Total embedded bytes (reported by `pli version`).
size_t embeddedSysrootSize();
} // namespace pli
